import { useValues } from 'kea'
import { useEffect, useRef, useState } from 'react'
import { createPortal } from 'react-dom'

import { IconTrash } from '@posthog/icons'
import { LemonButton, LemonMenu, LemonMenuItems } from '@posthog/lemon-ui'

import { richContentEditorLogic } from 'lib/components/RichContentEditor/richContentEditorLogic'
import { IconDragHandle } from 'lib/lemon-ui/icons'

import { TTEditor } from '../../../lib/components/RichContentEditor/types'

// Width of the invisible strip between the handle and the table, so moving the cursor
// from a cell to its handle never passes over "nothing" and makes the handle flicker
const HANDLE_GUTTER = 24

type MenuKind = 'row' | 'column'

function findEditableCell(target: EventTarget | null, editorDom: HTMLElement): HTMLTableCellElement | null {
    if (!(target instanceof Element)) {
        return null
    }
    const cell = target.closest('td, th')
    // Tables rendered inside notebook nodes (e.g. LemonTable) are not part of the document
    if (!(cell instanceof HTMLTableCellElement) || !editorDom.contains(cell) || cell.closest('.NotebookNode')) {
        return null
    }
    return cell
}

function runInCell(editor: TTEditor, cell: HTMLTableCellElement, command: (chain: any) => any): void {
    // Table commands act on the selected cell, so move the cursor into the hovered one first
    const pos = editor.view.posAtDOM(cell, 0)
    command(editor.chain().focus().setTextSelection(pos)).run()
}

export function TableMenu(): JSX.Element | null {
    const { ttEditor } = useValues(richContentEditorLogic)
    const [hoveredCell, setHoveredCell] = useState<HTMLTableCellElement | null>(null)
    const [openMenu, setOpenMenu] = useState<MenuKind | null>(null)
    // Rects are read from the live DOM on render, so scrolling only needs to trigger a re-render
    const [, setScrollTick] = useState(0)
    const handlesRef = useRef<HTMLDivElement>(null)
    const openMenuRef = useRef(openMenu)
    openMenuRef.current = openMenu

    useEffect(() => {
        if (!ttEditor) {
            return
        }
        const editorDom = ttEditor.view.dom

        const onMouseMove = (e: MouseEvent): void => {
            if (openMenuRef.current) {
                return
            }
            const cell = findEditableCell(e.target, editorDom)
            if (cell) {
                setHoveredCell(cell)
            } else if (!handlesRef.current?.contains(e.target as Node)) {
                setHoveredCell(null)
            }
        }
        const onMouseLeave = (e: MouseEvent): void => {
            if (openMenuRef.current || handlesRef.current?.contains(e.relatedTarget as Node)) {
                return
            }
            setHoveredCell(null)
        }
        const onScroll = (): void => setScrollTick((tick) => tick + 1)

        editorDom.addEventListener('mousemove', onMouseMove)
        editorDom.addEventListener('mouseleave', onMouseLeave)
        window.addEventListener('scroll', onScroll, true)
        return () => {
            editorDom.removeEventListener('mousemove', onMouseMove)
            editorDom.removeEventListener('mouseleave', onMouseLeave)
            window.removeEventListener('scroll', onScroll, true)
        }
    }, [ttEditor])

    if (!ttEditor || !ttEditor.isEditable || !hoveredCell || !hoveredCell.isConnected) {
        return null
    }

    const row = hoveredCell.parentElement
    const table = hoveredCell.closest('table')
    if (!row || !table) {
        return null
    }

    const tableRect = table.getBoundingClientRect()
